  .header {
    text-align: center;
    border-bottom: 2px solid var(--accent-color);
    padding-bottom: 10px;
    margin-bottom: 15px;
  }

  .logo {
    font-family: 'Cinzel', serif;
    font-size: 18px;
    font-weight: 700;
    color: var(--accent-color);
    letter-spacing: 1px;
  }

  .sub-header {
    font-size: 10px;
    color: var(--secondary-color);
    text-transform: uppercase;
    letter-spacing: 2px;
    margin-top: 5px;
  }

  .content {
    font-size: 12px;
    line-height: 1.6;
  }

  .field {
    margin-bottom: 10px;
    display: flex;
    align-items: baseline;
  }

  .label {
    font-weight: 700;
    color: var(--secondary-color);
    width: 80px;
    flex-shrink: 0;
    font-size: 11px;
  }

  .value {
    color: var(--text-color);
    border-bottom: 1px dotted #999;
    flex-grow: 1;
    padding-left: 5px;
    font-family: 'Courier New', monospace;
  }

  .stamp {
    position: absolute;
