    font-size: 14px;
    transform: rotate(-15deg);
    opacity: 0.8;
    pointer-events: none;
    text-transform: uppercase;
  }

  .notes-section {
    margin-top: 15px;
    border-top: 1px solid #ccc;
    padding-top: 10px;
  }

  .notes-title {
    font-weight: 700;
    font-size: 12px;
    margin-bottom: 5px;
    color: var(--accent-color);
  }

  .handwritten {
    font-family: 'Dancing Script', cursive; 
    font-style: italic;
    color: #000080;
    font-size: 13px;
    background: rgba(255, 255, 255, 0.5);
    padding: 5px;
    border-radius: 3px;
    position: relative;
  }

  .handwritten::after {
    content: '';
    position: absolute;
    bottom: 0;
    right: 0;
    width: 10px;
    height: 10px;
    background: url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxMCIgaGVpZ2h0PSIxMCI+PHBhdGggZD0iTTAgMTBMMTAgMEwxMCAxMFoiIGZpbGw9IiMwMDAwODAiLz48L3N2Zz4=') no-repeat;
    opacity: 0.5;
  }

  .signature {
    text-align: right;
    margin-top: 20px;
    font-family: 'Cinzel', serif;
    font-size: 12px;
    color: var(--text-color);
  }

  .btn-reveal {
    display: block;
    width: 100%;
    padding: 8px;
    margin-top: 15px;
    background-color: var(--text-color);
    color: #fff;
    border: none;
    font-family: 'Noto Serif SC', serif;
    font-size: 12px;
    cursor: pointer;
    transition: background-color 0.3s;
    text-align: center;
  }

  .btn-reveal:hover {
    background-color: var(--accent-color);
  }

  .hidden-layer {
    display: none;
    margin-top: 10px;
    padding: 10px;
    background-color: rgba(139, 0, 0, 0.05);
    border-left: 2px solid var(--accent-color);
  }

  .hidden-text {
      font-size: 11px;
      color: var(--accent-color);
  }


  @keyframes stamp-in {
    0% { transform: scale(2) rotate(-15deg); opacity: 0; }
    100% { transform: scale(1) rotate(-15deg); opacity: 0.8; }
  }

  .stamp.animate {
      animation: stamp-in 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
  }

</style>
